public class ReceiptPrinterTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected [" + expected + "] but got [" + actual + "]");
            failures++;
        }
    }

    static String capture(String[] items, double[] prices) {
        java.io.ByteArrayOutputStream buf = new java.io.ByteArrayOutputStream();
        java.io.PrintStream old = System.out;
        System.setOut(new java.io.PrintStream(buf));
        try {
            ReceiptPrinter.printReceipt(items, prices);
        } finally {
            System.setOut(old);
        }
        return buf.toString().replace(System.lineSeparator(), "\n");
    }

    public static void main(String[] args) {
        java.util.Locale.setDefault(java.util.Locale.US);
        check("two items",
                "milk: $2.50\neggs: $3.25\ntotal: $5.75\n",
                capture(new String[]{"milk", "eggs"}, new double[]{2.5, 3.25}));
        check("single item",
                "soap: $4.00\ntotal: $4.00\n",
                capture(new String[]{"soap"}, new double[]{4.0}));
        check("empty receipt",
                "total: $0.00\n",
                capture(new String[0], new double[0]));
        check("rounding to two decimals",
                "gum: $0.10\nmint: $0.20\ntotal: $0.30\n",
                capture(new String[]{"gum", "mint"}, new double[]{0.1, 0.2}));
        check("three items",
                "pen: $1.25\npad: $2.75\nink: $10.00\ntotal: $14.00\n",
                capture(new String[]{"pen", "pad", "ink"}, new double[]{1.25, 2.75, 10.0}));
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

