public class ReceiptPrinter {

    public static void printReceipt(String[] items, double[] prices) {
        double total = 0.0;
        for (int i = 0; i < items.length; i++) {
            System.out.printf("%s: $%.2f%n", items[i], prices[i]);
            total += prices[i];
        }
        System.out.printf("total: $%.2f%n", total);
    }
}
